INSERT INTO `celestial_cards` (`id`, `numeral`, `symbol`, `name`, `meaning`) VALUES
(1, 'I', '👑', 'The Crown', 'Kekuasaan dan wibawa menghampiri Anda. Ambil kendali.'),
(2, 'II', '🔥', 'The Inferno', 'Semangat membara. Transformasi besar sedang terjadi.'),
(3, 'III', '🌊', 'The Abyss', 'Kedalaman jiwa. Rahasia besar akan terungkap.'),
(4, 'IV', '⚡', 'The Surge', 'Energi tak terduga. Peluang datang secepat kilat.'),
(5, 'V', '🌙', 'The Eclipse', 'Perubahan fase. Biarkan yang lama pergi.'),
(6, 'VI', '💎', 'The Prism', 'Kejelasan pikiran. Keputusan Anda tepat hari ini.'),
(7, 'VII', '🦅', 'The Ascent', 'Ambisi tinggi. Anda sedang naik ke puncak.'),
(8, 'VIII', '⏳', 'The Epoch', 'Kesabaran menghasilkan buah. Waktu ada di pihak Anda.'),
(9, 'IX', '🗝️', 'The Key', 'Jawaban yang Anda cari sudah ada di tangan.'),
(10, 'X', '🌀', 'The Vortex', 'Perputaran takdir. Terima arusnya, jangan melawan.'),
(11, 'XI', '🛡️', 'The Bastion', 'Perlindungan kuat. Orang-orang Anda setia.'),
(12, 'XII', '🌟', 'The Nova', 'Ledakan potensi. Saatnya bersinar terang.'),
(13, 'XIII', '🐍', 'The Serpent', 'Kebijaksanaan tersembunyi. Perhatikan tanda-tanda.'),
(14, 'XIV', '⚖️', 'The Balance', 'Harmoni sempurna. Semuanya selaras hari ini.'),
(15, 'XV', '🔮', 'The Oracle', 'Intuisi paling tajam. Percayai insting Anda.'),
(16, 'XVI', '🏔️', 'The Summit', 'Anda di ambang pencapaian terbesar. Jangan berhenti.'),
(17, 'XVII', '🌹', 'The Rose', 'Keindahan dalam duri. Cinta dan pengorbanan berjalan bersama.'),
(18, 'XVIII', '🦁', 'The Legion', 'Kekuatan kolektif. Pasukan Anda siap bertempur.'),
(19, 'XIX', '🎭', 'The Masque', 'Ada topeng yang perlu dilepas. Tunjukkan wajah asli.'),
(20, 'XX', '🧭', 'The Compass', 'Arah sudah jelas. Ikuti kompas internal Anda.'),
(21, 'XXI', '🕊️', 'The Dove', 'Perdamaian datang setelah badai. Tenangkan hati.'),
(22, 'XXII', '⚔️', 'The Blade', 'Ketajaman logika. Potong semua yang menghambat.'),
(23, 'XXIII', '🌋', 'The Eruption', 'Energi yang tertahan meledak. Gunakan dengan bijak.'),
(24, 'XXIV', '🦊', 'The Fox', 'Kecerdikan adalah senjata utama. Bergerak dengan halus.'),
(25, 'XXV', '🏛️', 'The Pillar', 'Anda adalah fondasi. Tanpa Anda, segalanya runtuh.'),
(26, 'XXVI', '🌌', 'The Cosmos', 'Perspektif lebih besar. Lihat gambaran utuh semesta.'),
(27, 'XXVII', '🐺', 'The Wolf', 'Naluri berburu yang kuat. Percaya pada insting liar.'),
(28, 'XXVIII', '🪶', 'The Quill', 'Kata-kata Anda punya kuasa. Tulis sejarah Anda sendiri.'),
(29, 'XXIX', '⚓', 'The Anchor', 'Stabilitas di tengah badai. Anda adalah jangkar tim.'),
(30, 'XXX', '🔔', 'The Bell', 'Sinyal penting akan datang. Dengarkan baik-baik.'),
(31, 'XXXI', '🌿', 'The Root', 'Kembali ke akar. Kekuatan terbesar ada di asal usul.'),
(32, 'XXXII', '🎯', 'The Mark', 'Fokus tanpa kompromi. Bidik sekali, tembak sekali.'),
(33, 'XXXIII', '🕰️', 'The Hour', 'Momentum sempurna. Jam ini adalah jam Anda.'),
(34, 'XXXIV', '🦋', 'The Chrysalis', 'Metamorfosis. Versi terbaik Anda sedang dilahirkan.'),
(35, 'XXXV', '🏹', 'The Arrow', 'Ditarik mundur untuk melesat jauh ke depan.'),
(36, 'XXXVI', '🌅', 'The Dawn', 'Babak baru dimulai. Tinggalkan kegelapan di belakang.'),
(37, 'XXXVII', '🐉', 'The Dragon', 'Kekuatan legendaris bangkit dari dalam diri.'),
(38, 'XXXVIII', '💫', 'The Comet', 'Langka dan bercahaya. Kehadiran Anda tak terlupakan.'),
(39, 'XXXIX', '🔱', 'The Trident', 'Tiga kekuatan bersatu: pikiran, hati, dan tindakan.'),
(40, 'XL', '🧊', 'The Glacier', 'Tenang di permukaan, dahsyat di kedalaman.'),
(41, 'XLI', '🌠', 'The Wish', 'Harapan terdalam akan segera terwujud. Tetap yakin.'),
(42, 'XLII', '♾️', 'The Infinite', 'Tidak ada batas. Potensi Anda melampaui imajinasi.'),
