INSERT INTO `divine_verses` (`id`, `arabic`, `latin`, `meaning`, `source`) VALUES
(1, 'فَإِنَّ مَعَ الْعُسْرِ يُسْرًا', 'Fa inna ma\'al \'usri yusraa', 'Maka sesungguhnya bersama kesulitan ada kemudahan.', 'QS. Al-Insyirah: 5'),
(2, 'إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', 'Innallaha ma\'as-shaabirin', 'Sesungguhnya Allah bersama orang-orang yang sabar.', 'QS. Al-Baqarah: 153'),
(3, 'وَتَوَكَّلْ عَلَى اللَّهِ ۚ وَكَفَىٰ بِاللَّهِ وَكِيلًا', 'Wa tawakkal \'alallah, wa kafaa billahi wakeelaa', 'Dan bertawakallah kepada Allah. Dan cukuplah Allah sebagai pelindung.', 'QS. Al-Ahzab: 3'),
(4, 'وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا', 'Wa man yattaqillaha yaj\'al lahu makhrajaa', 'Barangsiapa bertakwa kepada Allah, niscaya Dia akan membukakan jalan keluar baginya.', 'QS. At-Talaq: 2'),
(5, 'رَبِّ اشْرَحْ لِي صَدْرِي', 'Rabbisy-rahli shadri', 'Ya Tuhanku, lapangkanlah dadaku.', 'QS. Taha: 25'),
(6, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ', 'Wa lasaufa yu\'tiika rabbuka fatardaa', 'Dan kelak Tuhanmu pasti memberikan karunia-Nya kepadamu, sehingga engkau menjadi puas.', 'QS. Ad-Duha: 5'),
(7, 'إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ', 'Innallaha laa yudii\'u ajral muhsiniin', 'Sesungguhnya Allah tidak menyia-nyiakan pahala orang yang berbuat baik.', 'QS. At-Taubah: 120'),
(8, 'وَاللَّهُ خَيْرُ الرَّازِقِينَ', 'Wallahu khairur-raaziqiin', 'Dan Allah adalah sebaik-baik pemberi rezeki.', 'QS. Al-Jumu\'ah: 11'),
(9, 'لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا', 'Laa tahzan innallaha ma\'anaa', 'Janganlah engkau bersedih, sesungguhnya Allah bersama kita.', 'QS. At-Taubah: 40'),
(10, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ', 'Wa nahnu aqrabu ilaihi min hablil wariid', 'Dan Kami lebih dekat kepadanya daripada urat lehernya sendiri.', 'QS. Qaf: 16'),
(11, 'ادْعُونِي أَسْتَجِبْ لَكُمْ', 'Ud\'uunii astajib lakum', 'Berdoalah kepada-Ku, niscaya akan Aku perkenankan bagimu.', 'QS. Ghafir: 60'),
(12, 'إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ', 'Innallaha yuhibbul mutawakkiliin', 'Sesungguhnya Allah menyukai orang-orang yang bertawakal.', 'QS. Ali Imran: 159'),
(13, 'فَاذْكُرُونِي أَذْكُرْكُمْ', 'Fadzkuruunii adzkurkum', 'Maka ingatlah kepada-Ku, niscaya Aku akan mengingat kalian.', 'QS. Al-Baqarah: 152'),
(14, 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا', 'Laa yukallifullaahu nafsan illaa wus\'ahaa', 'Allah tidak membebani seseorang melainkan sesuai kesanggupannya.', 'QS. Al-Baqarah: 286'),
(15, 'وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ', 'Wa \'asaa an takrahuu syai\'an wa huwa khairul lakum', 'Boleh jadi kamu membenci sesuatu padahal ia amat baik bagimu.', 'QS. Al-Baqarah: 216'),
(16, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'Iyyaaka na\'budu wa iyyaaka nasta\'iin', 'Hanya kepada Engkaulah kami menyembah dan hanya kepada Engkaulah kami mohon pertolongan.', 'QS. Al-Fatihah: 5'),
(17, 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fa bi\'ayyi aalaa\'i rabbikumaa tukadzdzibaan', 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?', 'QS. Ar-Rahman: 13'),
(18, 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ', 'Allahu laa ilaaha illaa huwal hayyul qayyuum', 'Allah, tidak ada tuhan selain Dia. Yang Mahahidup, Yang terus-menerus mengurus (makhluk-Nya).', 'QS. Al-Baqarah: 255'),
(19, 'قُلْ هُوَ اللَّهُ أَحَدٌ', 'Qul huwallahu ahad', 'Katakanlah (Muhammad), \"Dialah Allah, Yang Maha Esa\".', 'QS. Al-Ikhlas: 1'),
(20, 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ', 'Wa idzaa sa\'alaka \'ibaadii \'annii fa innii qariib', 'Dan apabila hamba-hamba-Ku bertanya kepadamu (Muhammad) tentang Aku, maka sesungguhnya Aku dekat.', 'QS. Al-Baqarah: 186'),
(21, 'لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ', 'La\'in syakartum la aziidannakum', 'Sesungguhnya jika kamu bersyukur, niscaya Aku akan menambah (nikmat) kepadamu.', 'QS. Ibrahim: 7'),
(22, 'أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ', 'Ahasiban naasu ayyutrokuu ayyaquuluu aamannaa wa hum laa yuftanuun', 'Apakah manusia mengira bahwa mereka dibiarkan hanya dengan mengatakan, \"Kami telah beriman,\" dan mereka tidak diuji?', 'QS. Al-\'Ankabut: 2'),
(23, 'لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ', 'Laa taqnathuu mir rahmatillaah', 'Janganlah kamu berputus asa dari rahmat Allah.', 'QS. Az-Zumar: 53'),
(24, 'وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 'Wa laa tahinuu wa laa tahzanuu wa antumul a\'launa in kuntum mu\'miniin', 'Janganlah kamu bersikap lemah, dan janganlah pula kamu bersedih hati, padahal kamulah orang-orang yang paling tinggi derajatnya, jika kamu orang-orang yang beriman.', 'QS. Ali Imran: 139'),
(25, 'وَاصْبِرُوا ۚ إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', 'Wasbiruu innallaha ma\'as-shaabiriin', 'Dan bersabarlah. Sesungguhnya Allah beserta orang-orang yang sabar.', 'QS. Al-Anfal: 46'),
(26, 'وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ', 'Wa ufawwidu amrii ilallaah', 'Dan aku menyerahkan urusanku kepada Allah.', 'QS. Ghafir: 44'),
(27, 'وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ', 'Wasta\'iinuu bis shabri was shalaah', 'Dan mohonlah pertolongan (kepada Allah) dengan sabar dan salat.', 'QS. Al-Baqarah: 45'),
(28, 'فَاصْبِرْ صَبْرًا جَمِيلًا', 'Fashbir shabran jamiilaa', 'Maka bersabarlah engkau (Muhammad) dengan kesabaran yang baik.', 'QS. Al-Ma\'arij: 5'),
(29, 'قُل لَّن يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا', 'Qul lan yushiibanaa illaa maa kataballahu lanaa', 'Katakanlah: \"Sekali-kali tidak akan menimpa kami melainkan apa yang telah ditetapkan oleh Allah bagi kami.\"', 'QS. At-Taubah: 51'),
(30, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا', 'Rabbanaa laa tuzigh quluubanaa ba\'da idz hadaitanaa', 'Ya Tuhan kami, janganlah Engkau condongkan hati kami kepada kesesatan setelah Engkau berikan petunjuk kepada kami.', 'QS. Ali Imran: 8'),
(31, 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ', 'Rabbanaa hab lanaa min azwaajinaa wa dzurriyyaatinaa qurrata a\'yun', 'Ya Tuhan kami, anugerahkanlah kepada kami pasangan kami dan keturunan kami sebagai penyenang hati.', 'QS. Al-Furqan: 74'),
(32, 'الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا', 'Alladzii khalaqal mawta wal hayaata liyabluwakum ayyukum ahsanu \'amalaa', 'Yang menciptakan mati dan hidup, untuk menguji kamu, siapa di antara kamu yang lebih baik amalnya.', 'QS. Al-Mulk: 2'),
(33, 'أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ', 'Alaa bidzikrillaahi tathma\'innul quluub', 'Ingatlah, hanya dengan mengingat Allah hati menjadi tenteram.', 'QS. Ar-Ra\'d: 28'),
(34, 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً', 'Rabbanaa aatinaa fid-dunyaa hasanah wa fil-aakhirati hasanah', 'Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat.', 'QS. Al-Baqarah: 201'),
(35, 'اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ', 'Allahu nuurus-samaawaati wal ardh', 'Allah (Pemberi) cahaya (kepada) langit dan bumi.', 'QS. An-Nur: 35'),
(36, 'وَقُل رَّبِّ زِدْنِي عِلْمًا', 'Wa qul rabbi zidnii \'ilmaa', 'Dan katakanlah, \"Ya Tuhanku, tambahkanlah ilmu kepadaku.\"', 'QS. Taha: 114'),
(37, 'رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ', 'Rabbi laa tadzarnii fardaw wa anta khairul waaritsiin', 'Ya Tuhanku, janganlah Engkau biarkan aku hidup seorang diri (tanpa keturunan) dan Engkaulah pewaris yang terbaik.', 'QS. Al-Anbiya: 89'),
(38, 'رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ', 'Rabbi innii limaa anzalta ilayya min khairin faqiir', 'Ya Tuhanku, sesungguhnya aku sangat memerlukan sesuatu kebaikan (makanan) yang Engkau turunkan kepadaku.', 'QS. Al-Qasas: 24'),
(39, 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ', 'Yaa ayyuhal ladziina aamanut-taqullaha wal tanzhur nafsum maa qaddamat lighad', 'Wahai orang-orang yang beriman! Bertakwalah kepada Allah dan hendaklah setiap orang memperhatikan apa yang telah diperbuatnya untuk hari esok.', 'QS. Al-Hasyr: 18'),
(40, 'وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا', 'Wamaa tuqaddimuu li\'anfusikum min khairin tajiduuhu \'indallaahi huwa khairaw wa a\'zhama ajraa', 'Dan kebaikan apa saja yang kamu perbuat untuk dirimu, niscaya kamu memperoleh (balasan)nya di sisi Allah sebagai balasan yang paling baik dan yang paling besar pahalanya.', 'QS. Al-Muzzammil: 20'),
(41, 'رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', 'Rabbir-hamhumaa kamaa rabbayaanii shaghiiraa', 'Ya Tuhanku, sayangilah keduanya sebagaimana mereka berdua telah mendidik aku pada waktu kecil.', 'QS. Al-Isra: 24'),
(42, 'رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', 'Rabbanaa aatinaa mil ladunka rahmatan wa hayyi\' lanaa min amrinaa rasyadaa', 'Ya Tuhan kami, berikanlah rahmat kepada kami dari sisi-Mu dan sempurnakanlah petunjuk yang lurus bagi kami dalam urusan kami.', 'QS. Al-Kahf: 10'),
(43, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', 'Wa innaka la\'alaa khuluqin \'azhiim', 'Dan sesungguhnya engkau (Muhammad) benar-benar berbudi pekerti yang agung.', 'QS. Al-Qalam: 4'),
(44, 'إِنَّا هَدَيْنَاهُ السَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', 'Innaa hadainaahus-sabiila immaa syaakiraw wa immaa kafuuraa', 'Sungguh, Kami telah menunjukkan kepadanya jalan yang lurus; ada yang bersyukur dan ada pula yang kufur.', 'QS. Al-Insan: 3'),
(45, 'إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ', 'Innamal mu\'minuunal-ladziina idzaa dzukirallahu wajilat quluubuhum', 'Sesungguhnya orang-orang yang beriman adalah mereka yang apabila disebut nama Allah gemetar hatinya.', 'QS. Al-Anfal: 2'),
(46, 'وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَىٰ مَا أَصَابَكَ', 'Wamur bil-ma\'ruufi wanha \'anil-munkari wasbir \'alaa maa ashaabak', 'Suruhlah (manusia) berbuat yang makruf dan cegahlah (mereka) dari yang mungkar dan bersabarlah terhadap apa yang menimpamu.', 'QS. Luqman: 17'),
(47, 'فَلَا تَعْلَمُ نَفْسٌ مَّا أُخْفِيَ لَهُم مِّن قُرَّةِ أَعْيُنٍ', 'Falaa ta\'lamu nafsum maa ukhfiya lahum min qurrati a\'yun', 'Maka tidak seorang pun mengetahui apa yang disembunyikan untuk mereka yaitu (bermacam-macam nikmat) yang menyedapkan pandangan mata.', 'QS. As-Sajdah: 17'),
(48, 'إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ', 'Innalladziina qaaluu rabbunallahu tsummas taqaamuu tatanazzalu \'alaihimul malaa\'ikah', 'Sesungguhnya orang-orang yang berkata, \"Tuhan kami adalah Allah\" kemudian mereka meneguhkan pendirian mereka, maka malaikat-malaikat akan turun kepada mereka.', 'QS. Fussilat: 30'),
(49, 'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', 'Innaa fatahnaa laka fat-ham mubiinaa', 'Sungguh, Kami telah memberikan kepadamu kemenangan yang nyata.', 'QS. Al-Fath: 1'),
(50, 'إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ', 'Innamaa amruhuu idzaa araada syai\'an ay-yaquula lahuu kun fa yakuun', 'Sesungguhnya urusan-Nya apabila Dia menghendaki sesuatu Dia hanya berkata kepadanya, \"Jadilah!\" Maka jadilah sesuatu itu.', 'QS. Yasin: 82');
