(509, 'radar_info_profile', 'Lihat Profil', 'text', '2026-06-04 18:12:18', '2026-06-04 18:12:18'),
(510, 'galeri_indicator_cover', 'COVER DEPAN', 'text', '2026-06-04 18:12:19', '2026-06-04 18:12:19'),
(511, 'offline_title', 'Koneksi Terputus', 'text', '2026-06-04 20:29:19', '2026-06-04 20:29:19'),
(512, 'offline_desc', 'Anda sedang tidak terhubung ke jaringan. Beberapa fitur mungkin tidak tersedia dalam mode offline.', 'text', '2026-06-04 20:29:19', '2026-06-04 20:29:19'),
(513, 'offline_btn_retry', 'Coba Ulang', 'text', '2026-06-04 20:29:19', '2026-06-04 20:29:19'),
(514, 'landing_stat_1_label', 'Entitas', 'text', '2026-06-04 20:29:20', '2026-06-04 20:29:20'),
(515, 'landing_scroll_hint', 'Gulir', 'text', '2026-06-04 20:29:20', '2026-06-04 20:29:20'),
(516, 'beranda_lore_1', '\"Dan bersabarlah kamu bersama-sama dengan orang-orang yang menyeru Tuhannya di pagi dan senja hari...\" (Al-Kahfi: 28)', 'text', '2026-06-04 21:00:18', '2026-06-04 21:00:18'),
(517, 'beranda_lore_2', '\"Niscaya Allah akan meninggikan orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu pengetahuan...\" (Al-Mujadilah: 11)', 'text', '2026-06-04 21:00:18', '2026-06-04 21:00:18'),
(518, 'beranda_lore_3', '\"Dan berpeganglah kamu semuanya kepada tali (agama) Allah, dan janganlah kamu bercerai berai...\" (Ali Imran: 103)', 'text', '2026-06-04 21:00:18', '2026-06-04 21:00:18'),
(519, 'beranda_lore_4', '\"Maka sesungguhnya sesudah kesulitan itu ada kemudahan...\" (Al-Insyirah: 5)', 'text', '2026-06-04 21:00:18', '2026-06-04 21:00:18'),
(520, 'beranda_lore_5', '\"Bukanlah golongan kami orang yang tidak menyayangi yang muda dan tidak menghormati yang tua.\" (HR. Tirmidzi)', 'text', '2026-06-04 21:00:18', '2026-06-04 21:00:18'),
(521, 'beranda_shard1_title', 'Bumi dengan 2 Lafazd Syahadat, Pena Bulu Emas dan Dua Kitab', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(522, 'beranda_shard1_desc', 'Melambangkan yang menyiratkan makna QS. Al-Baqarah : 30 sebagai pemimpin di bumi yang mempunyai misi dalam menyebarluaskan ajaran, nilai, dan syariat Islam yang benar ke seluruh jagat raya. Pena bulu emas dan dua kitab melambangkan kewajiban alumni Expedient Generation, dalam menjalankan amanah yang berdasarkan Al-Quran\'an & As - Sunnah.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(523, 'beranda_shard2_title', 'Tulisan Almamater', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(524, 'beranda_shard2_desc', 'Sebagai doa agar alumni Arrisalah tahun 2025 menjadi alumni yang husnul khotimah dan membangun kejayaan risalah Nabi Muhammad SAW.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(525, 'beranda_shard3_title', 'Cincin Emas', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(526, 'beranda_shard3_desc', 'Cincin emas bermakna kekuatan dan sesuatu yang berharga, melambangkan tekat yang kuat, serta karakter yang visioner.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(527, 'beranda_shard4_title', 'Selendang Berwarna Putih', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(528, 'beranda_shard4_desc', 'Selendang melambangkan persaudaraan yang erat dan solid, berdasarkan asas iman dan agama Islam yang harus dijaga kesuciannya.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(529, 'beranda_shard5_title', 'Bendera Pondok Modern', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(530, 'beranda_shard5_desc', 'Merupakan simbol Pondok Modern sebagai lembaga pendidikan yang selalu berada di atas dan untuk semua golongan.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(531, 'beranda_shard6_title', 'Kelopak Logam Mulia Tungsten', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(532, 'beranda_shard6_desc', 'Kelopak logam mulia tungsten merupakan material terkuat di dunia yang melambangkan perisai diri yang kuat dari godaan syaitan yang terkutuk.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(533, 'beranda_shard7_title', 'Perisai Rub Al-Hizb', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(534, 'beranda_shard7_desc', 'Bentuk segi delapan ini merepresentasikan Rub Al-Hizb, simbol klasik pembatas ayat Al-Qur\'an, yang melambangkan komitmen alumni sebagai benteng iman dan pengamal kalam suci. Delapan sudutnya melambangkan delapan pintu surga sekaligus kesiapan menyebarkan kemaslahatan rahmatan lil-\'alamin ke delapan penjuru mata angin. Dibalut kilau perak (Al-Fidhdhah) yang terinspirasi dari keindahan perhiasan surga (QS. Al-Insan: 21), simbol ini menegaskan karakter alumni yang tangguh, adaptif, dan berharga tinggi, namun tetap bersahaja dalam kerendahan hati (tawadhu).', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(535, 'beranda_shard8_title', 'Kelopak Blue Marble', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(536, 'beranda_shard8_desc', 'Merupakan sebutan pertama kali untuk foto bumi yang pertama, yang diambil pada 7 Desember 1972, melambangkan gerakan dalam menjaga dan melestarikan bumi sebagai amanah yang dibebankan kepada seluruh umat manusia sesuai dengan QS. Al-Baqarah: 56. Memicu perlunya pembangkitan berkelanjutan untuk menjaga planet. Kepercayaan, loyalitas, tanggung jawab, keamanan simbol surga spiritualitas. Dan berlist-kan emas melambangkan bahwa alumni Arrisalah tahun 2025 adalah sesuatu yang berharga.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(537, 'beranda_shard9_title', 'Tanduk Rusa Emas Berlafazkan Muhammad SAW', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(538, 'beranda_shard9_desc', 'Melambangkan semangat yang tinggi dalam menggapai cita-cita yang mulia, sebagai simbol regenerasi dan kebangkitan risalah Nabi Muhammad SAW. Kehadiran batu rubi merah di poros tengah bawah mengambil makna dari istilah bahasa Sanskerta Ratna yang berarti permata paling berharga. Batu Ratna ini merepresentasikan prinsip ketauhidan sebagai pondasi utama yang tunggal dan utuh. Posisinya yang diletakkan di bagian paling bawah menegaskan bahwa seluruh pergerakan, semangat perjuangan, dan cita-cita alumni harus berakar kuat pada asas tauhid yang kokoh kepada Allah SWT.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(539, 'beranda_shard10_title', 'Perisai Baja Berbentuk Segi 8', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(540, 'beranda_shard10_desc', 'Menggambarkan asas Islam yang kokoh dan delapan arah mata angin yang memberi dampak pemberdayaan potensi yang memancar ke seluruh penjuru alam (rahmatan lil-alamin), serta menyiratkan makna seperti dalam QS. Al-Baqarah: 115, yakni kemanapun kamu menghadap, disanalah wajah-Nya.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(541, 'beranda_shard11_title', 'Mahkota Emas Berlambangkan Allah SWT', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(542, 'beranda_shard11_desc', 'Melambangkan kekuasaan, keabadian, kebijaksanaan dan legitimasi. Simbol ini terletak di atas melambangkan bahwa Allah SWT yang Maha Esa dan segala aspek kehidupan ini bermuara kepada-Nya tiada daya dan upaya selain dari kehendak Allah Taala.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(543, 'beranda_shard12_title', 'Lima Permata', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(544, 'beranda_shard12_desc', 'Lima permata bermakna lima rukun Islam yang mendasari berdirinya agama Islam.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(545, 'beranda_shard13_title', 'Enam Batu Zamrud', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(546, 'beranda_shard13_desc', 'Enam batu zamrud sebagai simbol kemakmuran dan kelimpahan yang melambangkan enam rukun iman sebagai asas dasar keyakinan seorang muslim.', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(547, 'beranda_jiwa_ikhlas_title', '1. Keikhlasan', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(548, 'beranda_jiwa_ikhlas_desc', '<p>Jiwa yang pertama adalah keikhlasan. Prinsip ini berarti <em>sepi ing pamrih</em>, yakni berbuat sesuatu bukan karena didorong oleh keinginan untuk mendapatkan keuntungan tertentu, melainkan hanya untuk Allah SWT semata. Segala perbuatan dilakukan dengan niat semata-mata untuk ibadah, Lillah. Kiai dan guru ikhlas dalam mendidik, para pembantu Kiai ikhlas dalam membantu menjalankan proses pendidikan, serta para santri yang ikhlas dididik.</p><p>Jiwa ini menciptakan suasana kehidupan pondok yang harmonis antara Kiai yang disegani dengan santri yang taat, cinta dan penuh hormat. Jiwa ini pula yang menjadikan para santri senantiasa siap berjuang di jalan Allah, di manapun dan kapanpun.</p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(549, 'beranda_jiwa_sederhana_title', '2. Kesederhanaan', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(550, 'beranda_jiwa_sederhana_desc', '<p>Kehidupan yang sederhana tentu sangat erat kaitannya dengan pondok pesantren. Kehidupan santri yang tentram bersahaja tentu jauh dari kata berlebihan, mubazir dan lain sebagainya. Sederhana tidak berarti pasif atau menerima begitu saja, tidak juga berarti miskin dan melarat.</p><p>Justru dalam jiwa kesederhanan itu terdapat nilai-nilai kekuatan, kesanggupan, ketabahan dan penguasaan diri dalam menghadapi perjuangan hidup.</p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(551, 'beranda_jiwa_mandiri_title', '3. Kemandirian', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(552, 'beranda_jiwa_mandiri_desc', '<p>Kemandirian atau sering disebut juga dengan Berdikari (Berdiri di atas kaki sendiri) adalah kesanggupan menolong diri sendiri. Jiwa tersebut merupakan senjata ampuh yang dibekalkan pesantren kepada para santrinya. Berdikari tidak saja berarti bahwa santri sanggup belajar dan berlatih mengurus segala kepentingannya sendiri, tetapi pondok pesantren itu sendiri sebagai lembaga pendidikan juga harus sanggup berdikari sehingga tidak pernah menyandarkan kehidupannya kepada bantuan atau belas kasihan pihak lain.</p><p>Gontor menerapkan <em>Zelp-Berdruiping Systeem</em> (sama-sama memberikan iuran dan sama-sama memakai). Semua pekerjaan yang ada di dalam pondok dikerjakan oleh Kiai, guru dan para santrinya sendiri.</p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(553, 'beranda_jiwa_ukhuwah_title', '4. Ukhuwwah Islamiyyah', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(554, 'beranda_jiwa_ukhuwah_desc', '<p>Kehidupan di pondok pesantren diliputi suasana persaudaraan yang akrab, sehingga segala suka dan duka dirasakan bersama dalam jalinan ukhuwwah Islamiyyah. Tidak ada dinding pemisah di antara mereka; apapun latarbelakang keluarga, suku, budaya, bahkan bangsa semua larut dalam jalinan ukhuwwah Islamiyyah.</p><p>Ukhuwah ini bukan saja selama mereka di Pondok, tetapi juga mempengaruhi ke arah persatuan umat dalam masyarakat setelah mereka terjun di masyarakat.</p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(555, 'beranda_jiwa_bebas_title', '5. Kebebasan', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(556, 'beranda_jiwa_bebas_desc', '<p>Bebas dalam berpikir dan berbuat, bebas dalam menentukan masa depan, bebas dalam memilih jalan hidup, dan bahkan bebas dari berbagai pengaruh negatif dari luar dirinya. Jiwa bebas ini akan menjadikan santri berjiwa besar dan optimis dalam menghadapi segala kesulitan.</p><p>Seringkali ditemukan unsur-unsur negatif dari kebebasan yang tak terkontrol, yaitu apabila kebebasan itu disalahgunakan, sehingga terlalu bebas (liberal) dan berakibat hilangnya arah tujuan dan prinsip. Ada pula yang terlalu bebas (untuk tidak mau dipengaruhi), berpegang teguh kepada tradisi yang dianggapnya baik, sehingga tidak mau mengikuti perkembangan zaman.</p><p>Maka kebebasan ini harus dikembalikan ke aslinya, yaitu bebas di dalam garis-garis yang positif, dengan penuh tanggungjawab; baik di dalam kehidupan pondok pesantren itu sendiri, maupun dalam kehidupan masyarakat. Untuk bisa mendapatkan kebebasan, seorang santri haruslah memegang teguh 4 prinsip sebelumnya agar tidak terjerumus ke dalam kebebasan yang salah.</p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(557, 'beranda_arc1_date', '30 MARET 2026', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(558, 'beranda_arc1_title', 'Deklarasi Visi Sovereign', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(559, 'beranda_arc1_content', '<p>Naskah ini mencatat sumpah agung angkatan Expedient mengenai visi dan arah tujuan masa depan.</p><p>Kami berjanji untuk memelihara warisan <span class=\"redacted\" onclick=\"revealRedacted(this)\">KEISLAMAN</span> dan mengikat erat <span class=\"redacted\" onclick=\"revealRedacted(this)\">PERSAUDARAAN</span>.</p><p>Nilai-nilai ini diukir bukan pada batu, melainkan pada karakter setiap individu.</p><p><em>Selesai.</em></p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(560, 'beranda_arc2_date', '15 FEBRUARI 2026', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(561, 'beranda_arc2_title', 'Simpul Kesucian: Menjaga Nilai Arrisalah', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
(562, 'beranda_arc2_content', '<p>Manuskrip mengenai pemeliharaan nilai-nilai murni dalam harmoni pasca-kelulusan.</p><p>Di balik kemewahan dunia, pondasi kita tetap bersandar pada <span class=\"redacted\" onclick=\"revealRedacted(this)\">KESEDERHANAAN</span> hati.</p><p>Setiap duta angkatan diharapkan menjadi mercusuar teladan di manapun mereka memijakkan kaki.</p><p><em>Tertanda, Dewan Kehormatan.</em></p>', 'text', '2026-06-04 21:00:19', '2026-06-04 21:00:19'),
